mp.mp.dps=40
# Limiting cycle factors for a complete bipartite graph having
# internal average degree d in its larger class, with size difference s.
def F(d,s):
    return (1+mp.mpf(d))**(mp.mpf(s)/2)*mp.besseli(s,2*mp.sqrt(1+d))
for d in [1,mp.mpf(4)/3,2,3,4]:
    print('d=',d)
    for parity in [0,1]:
        vals=[(s,F(d,s)) for s in range(parity,8,2)]
        print(' parity',parity,[(s,float(v)) for s,v in vals])
print('For d=3, odd n, F_3/F_1 =',F(3,3)/F(3,1))
# Edge objective for the expected W_9 extremal form: ab+floor(3a/2)+1.
for n in [43,47,51]:
    vals=[(a,a*(n-a)+(3*a)//2+1) for a in range(1,n)]
    M=max(v for a,v in vals)
    print('n=',n,'maximizing a=',[a for a,v in vals if v==M],
          'competitor a=',(n+3)//2,'edge deficit=',M-((n+3)//2*((n-3)//2)+(3*((n+3)//2))//2+1))"}

